167	\begin{definition}[Consistent measurements]\label{def:consistent-measurement}
168		\lean{MIPStarRE.QPBT.Measurement.IsConsistentOn}
169		\leanok
170		\uses{def:povm-conventions}
171		Let $\mathcal A$ be a finite set, let $\ket{\psi} \in \mathcal H \ot \mathcal H$ be a state, and let $\{M_a\}_{a \in \mathcal A}$ be a projective measurement on $\mathcal H$. We say that \emph{$\{M_a\}_{a \in \mathcal A}$ is consistent on $\ket{\psi}$} if and only if
172		\[
173			\forall a \in \mathcal A\,, \qquad M_a \ot \Id_B\, \ket{\psi} = \Id_A \ot M_a\, \ket{\psi}\,.
174		\]
175		When the state $\ket{\psi}$ is clear from context we simply say that $\{M_a\}_{a \in \mathcal A}$ is consistent.
176	\end{definition}
177	
178	The terminology arises from the fact that when the measurement $\{M_a\}$ is performed on both registers of $\ket{\psi}$, the probability of obtaining twice the same outcome is
179	\[
180		\sum_a \bra{\psi} M_a \ot M_a \ket{\psi} = \sum_a \bra{\psi} \Id_A \ot (M_a)^2 \ket{\psi} = \sum_a \bra{\psi} \Id_A \ot M_a \ket{\psi} = 1\,,
490		\]
491		for $k = 0$ the empty product is understood as the identity, so that $C^x$ is the measurement whose single outcome, the empty tuple, carries the operator $\Id$. Then on average over $x \sim \mu$ and $y \in \mathcal Y$ sampled uniformly at random,
492		\begin{equation}\label{eq:ld-sandwich-2}
493			A^x_{[\operatorname{eval}_y(\cdot) = (a_1,\,a_2,\,\dots,\,a_k)]} \ot \Id_B \simeq_{k(\delta+\eps)^{1/2}} \Id_A \ot C^x_{[\operatorname{eval}_y(\cdot) = (a_1,\,a_2,\,\dots,\,a_k)]}\,.
494		\end{equation}
495	\end{lemma}
496	\begin{proof}
497		The source proof is a citation: the argument is identical to the proof of Fact 4.34 in \cite{Natarajan2018NEEXP}, with the only modification being the insertion of the dependence on the question $x$ for all measurements considered. In outline, the consistency hypotheses \eqref{eq:ld-sandwich-1} allow one to insert the projective factors $G^{i,\,x}$ next to $A^x$ one index at a time, and the $\eps$-bound on the pairwise agreement of distinct functions in $\mathcal G_i$ controls the events on which two different outcomes collide at the sampled point $y$. Each of the $k$ insertions costs $(\delta+\eps)^{1/2}$ by the Cauchy--Schwarz inequality, producing the sandwich $C^x$ with total error $k(\delta+\eps)^{1/2}$.
498	\end{proof}
499	
500	\begin{remark}[Index pairing in the sandwich]\label{rem:ld-sandwich-indexing}
501		As printed in the source, the sandwich in Lemma~\ref{lem:ld-sandwich} pairs the $i$-th measurement with the outcome $g_{k+1-i}$: the outermost factor $G^{k,\,x}$ carries the outcome $g_1$ and the innermost factor $G^{1,\,x}$ carries $g_k$. Since the measurement $\{G^{i,\,x}_g\}$ is indexed by $g \in \mathcal G_i$, the operator $G^{k,\,x}_{g_1}$ is undefined whenever $\mathcal G_1 \ne \mathcal G_k$, so the printed pairing is a typographical slip. The statement above instead uses the pairing $G^{k,\,x}_{g_k} \cdots G^{1,\,x}_{g_1} \cdots G^{k,\,x}_{g_k}$ of Fact 4.34 in \cite{Natarajan2018NEEXP}, from which the lemma is imported. The source also leaves the case $k = 0$ implicit; with the empty-product convention recorded in the statement, both sides of \eqref{eq:ld-sandwich-2} are then the identity on the single empty-tuple outcome and the conclusion holds with error zero.
502	\end{remark}
